/* A Client surface module: the pointable code viewer. Runs on the drawing thread with no $;
   keys and the mouse move a cursor and selection, and actions are posted to the hooks module. */
import type { ClientKeyEvent, ClientModule, ClientPointerEvent, ClientSurface, RenderElement } from 'claude-code'

export type ViewerLine = { n: number; text: string; mark?: 'add' | 'mod'; removed?: string[] }
export type ViewerThread = { start: number; end: number; mode: 'ask' | 'change'; text: string; answer?: string; pending: boolean }
export type ViewerProps = {
  path: string
  lines: ViewerLine[]
  /** 1-based line to put the cursor on whenever `jump` changes. */
  cursor: number
  jump: number
  symbols: { name: string; start: number; end: number }[]
  threads: ViewerThread[]
  height: number
  reviewed: boolean
}
export type View = { cur: number; anchor: number | null; top: number; jump: number; showRemoved: boolean; open: number | null }
/** The listeners outlive one draw: they read the newest props and size through this. */
type State = View & { live: { p: ViewerProps; h: number } }

const C = {
  add: '#34d399', addBg: '#0f2e24', del: '#f87171', delBg: '#2e1215', sel: '#2b3350', cur: '#3b4470',
  gutter: '#5b6170', ask: '#60a5fa', change: '#fbbf24', dim: '#7c8191', thread: '#a78bfa',
}

const indexOf = (p: ViewerProps, n: number): number => {
  const f = p.lines.findIndex(l => l.n >= n)
  return f === -1 ? Math.max(0, p.lines.length - 1) : f
}
const isMarked = (l: ViewerLine | undefined) => !!(l && (l.mark || l.removed))
const symbolAt = (p: ViewerProps, n: number) =>
  [...p.symbols].filter(y => y.start <= n && n <= y.end).sort((a, b) => (a.end - a.start) - (b.end - b.start))[0]

/** One key: the next view, or a message for the hooks module. Pure, so it is easy to reason about. */
export function act(v: View, p: ViewerProps, h: number, k: ClientKeyEvent): { view?: View; post?: Record<string, unknown> } {
  const last = Math.max(0, p.lines.length - 1)
  const lo = Math.min(v.cur, v.anchor ?? v.cur), hi = Math.max(v.cur, v.anchor ?? v.cur)
  const move = (to: number, keep: boolean): View => {
    const cur = Math.max(0, Math.min(last, to))
    const top = cur < v.top ? cur : cur >= v.top + h ? cur - h + 1 : v.top
    return { ...v, cur, top, anchor: keep ? (v.anchor ?? v.cur) : null }
  }
  const sel = { start: p.lines[lo]?.n ?? 1, end: p.lines[hi]?.n ?? 1 }
  const extend = !!k.shift || v.anchor !== null
  switch (k.key) {
    case 'up': case 'k': return { view: move(v.cur - 1, extend) }
    case 'down': case 'j': return { view: move(v.cur + 1, extend) }
    case 'pageup': return { view: move(v.cur - h + 2, extend) }
    case 'pagedown': case ' ': return { view: move(v.cur + h - 2, extend) }
    case 'home': case 'g': return { view: move(0, false) }
    case 'end': case 'G': return { view: move(last, false) }
    case 'v': return { view: { ...v, anchor: v.anchor === null ? v.cur : null } }
    case 'n': {
      for (let i = v.cur + 1; i <= last; i++) if (isMarked(p.lines[i]) && !isMarked(p.lines[i - 1])) return { view: move(i, false) }
      return {}
    }
    case 'p': case 'N': {
      for (let i = v.cur - 1; i >= 0; i--) if (isMarked(p.lines[i]) && !isMarked(p.lines[i - 1])) return { view: move(i, false) }
      return {}
    }
    case 'f': {
      const sym = symbolAt(p, p.lines[v.cur]?.n ?? 1)
      if (!sym) return {}
      const a = indexOf(p, sym.start), b = indexOf(p, sym.end)
      return { view: { ...v, anchor: a, cur: b, top: Math.min(a, Math.max(v.top, b - h + 1)) } }
    }
    case 'x': return { view: { ...v, showRemoved: !v.showRemoved } }
    case 't': case 'return': {
      const n = p.lines[v.cur]?.n ?? 0
      const i = p.threads.findIndex(t => t.start <= n && n <= t.end)
      if (i === -1) return {}
      return { view: { ...v, open: v.open === i ? null : i } }
    }
    case 'a': return { post: { type: 'ask', mode: 'ask', ...sel }, view: { ...v, anchor: null } }
    case 'c': return { post: { type: 'ask', mode: 'change', ...sel }, view: { ...v, anchor: null } }
    case 'r': return { post: { type: 'reviewed' } }
    case 'left': case 'h': case 'backspace': return { post: { type: 'back' } }
    case ']': return { post: { type: 'file', step: 1 } }
    case '[': return { post: { type: 'file', step: -1 } }
  }
  return {}
}

export function pointer(v: View, p: ViewerProps, e: ClientPointerEvent): View | undefined {
  const i = Math.max(0, Math.min(p.lines.length - 1, v.top + e.y))
  if (e.type === 'down') return { ...v, cur: i, anchor: i }
  if (e.type === 'move' && v.anchor !== null) return { ...v, cur: i }
  if (e.type === 'up' && v.anchor === i && v.cur === i) return { ...v, anchor: null }
  return undefined
}

export const Viewer: ClientModule<ViewerProps, State> = (props, s: ClientSurface<State>) => {
  const { Box, Text } = s.elements
  const height = Math.max(4, Math.min(props.height, s.rows || props.height))
  let st = s.state
  const live = st?.live ?? { p: props, h: height }
  live.p = props
  live.h = height

  if (!st) {
    const cur = indexOf(props, props.cursor)
    st = { cur, anchor: null, top: Math.max(0, cur - Math.floor(height / 3)), jump: props.jump, showRemoved: true, open: null, live }
    s.setState(st)
    s.onKey(k => {
      const now = s.state
      if (!now) return
      const r = act(now, now.live.p, now.live.h, k)
      if (r.view) s.setState({ ...r.view, live: now.live })
      if (r.post) s.post(r.post as never)
    })
    s.onPointer(e => {
      const now = s.state
      if (!now) return
      const v = pointer(now, now.live.p, e)
      if (v) s.setState({ ...v, live: now.live })
    })
  } else if (st.jump !== props.jump) {
    // a file switch or a landed change: put the cursor where the hooks module says
    const cur = indexOf(props, props.cursor)
    st = { ...st, cur, anchor: null, top: Math.max(0, cur - Math.floor(height / 3)), jump: props.jump, open: null }
    s.setState(st)
  }

  const v = st
  const lo = Math.min(v.cur, v.anchor ?? v.cur), hi = Math.max(v.cur, v.anchor ?? v.cur)
  const width = Math.max(20, s.columns || 80)
  const gw = String(props.lines.at(-1)?.n ?? 1).length
  const codeW = Math.max(8, width - gw - 5)
  const out: RenderElement[] = []
  let used = 0
  for (let i = v.top; i < props.lines.length && used < height; i++) {
    const l = props.lines[i]!
    if (v.showRemoved && l.removed?.length) {
      for (const r of l.removed.slice(0, 4)) {
        if (used >= height) break
        out.push(
          <Box key={`d${i}-${used}`} flexDirection="row">
            <Text color={C.del}>{`${' '.repeat(gw + 1)}−│ `}</Text>
            <Text color={C.del} backgroundColor={C.delBg} wrap="truncate-end">{r.replace(/\t/g, '  ').slice(0, codeW)}</Text>
          </Box>,
        )
        used++
      }
      if (l.removed.length > 4 && used < height) {
        out.push(<Text key={`dm${i}`} color={C.del} dimColor>{`${' '.repeat(gw + 4)}… ${l.removed.length - 4} more removed`}</Text>)
        used++
      }
    }
    if (used >= height) break
    const inSel = i >= lo && i <= hi && v.anchor !== null
    const isCur = i === v.cur
    const bg = isCur ? C.cur : inSel ? C.sel : l.mark ? C.addBg : undefined
    const ti = props.threads.findIndex(t => t.end === l.n)
    out.push(
      <Box key={`l${i}`} flexDirection="row">
        <Text color={inSel || isCur ? C.change : C.gutter}>{`${inSel || isCur ? '▌' : ' '}${String(l.n).padStart(gw)}`}</Text>
        <Text color={l.mark ? C.add : C.gutter} bold={!!l.mark}>{`${l.mark ? '+' : ' '}│ `}</Text>
        <Text backgroundColor={bg} wrap="truncate-end">{(l.text.replace(/\t/g, '  ') || ' ').slice(0, codeW)}</Text>
        {ti !== -1 && <Text color={props.threads[ti]!.mode === 'ask' ? C.ask : C.change}>{props.threads[ti]!.pending ? ' ⧗' : ' ●'}</Text>}
      </Box>,
    )
    used++
    if (ti !== -1 && (v.open === ti || props.threads[ti]!.pending) && used < height) {
      const t = props.threads[ti]!
      const color = t.mode === 'ask' ? C.ask : C.change
      const wrapW = Math.max(10, width - gw - 8)
      const body = (t.pending ? [`${t.mode === 'ask' ? 'Asking' : 'Changing'}…`] : (t.answer ?? '').split('\n'))
        .flatMap(x => (x === '' ? [''] : x.match(new RegExp(`.{1,${wrapW}}`, 'g')) ?? ['']))
      const room = Math.max(1, Math.min(10, height - used - 3))
      out.push(
        <Box key={`t${i}`} flexDirection="column" borderStyle="round" borderColor={color} marginLeft={gw + 2}>
          <Text color={color} bold wrap="truncate-end">{`${t.mode === 'ask' ? '❓' : '✎'} ${t.text}`}</Text>
          {body.slice(0, room).map((x, j) => <Text key={`tb${j}`} wrap="truncate-end">{x}</Text>)}
          {body.length > room && <Text dimColor>{`… ${body.length - room} more lines in the transcript`}</Text>}
        </Box>,
      )
      used += Math.min(body.length, room) + 3
    }
  }
  const selN = hi - lo + 1
  const curLine = props.lines[v.cur]?.n ?? 0
  const sym = symbolAt(props, curLine)
  const onThread = props.threads.some(t => t.start <= curLine && curLine <= t.end)
  return (
    <Box flexDirection="column">
      {out}
      <Box flexDirection="row" columnGap={2}>
        <Text color={v.anchor !== null ? C.change : C.dim}>{v.anchor !== null ? `▌ ${selN} line${selN > 1 ? 's' : ''} selected · a ask · c change` : `line ${curLine}/${props.lines.at(-1)?.n ?? 0}`}</Text>
        {sym && <Text color={C.thread}>{`ƒ ${sym.name}`}</Text>}
        {onThread && v.anchor === null && <Text color={C.ask}>t note</Text>}
        {props.reviewed && <Text color={C.add}>✔ reviewed</Text>}
      </Box>
    </Box>
  )
}

export default Viewer

files.hooks/branch.ts:
/* Branch scope: the changes since the base branch, read from git and shaped like the session's
   model (edits + groups), so the same pane and viewer show them. No model call: each commit's
   subject is its concept; a file goes under the newest commit that touched it. */
import type { Edit, Group, Hunk, Model } from '../types'
import { EMPTY, slug, symbolAt } from './model.js'

export const GIT_ENV = { LC_ALL: 'C', LANGUAGE: '' } as const
export const NOLOCK = '--no-optional-locks'

/** Parses `git diff -U3` output into per-file hunks (renames read as their new path). */
export function parseDiff(out: string): Map<string, Hunk[]> {
  const files = new Map<string, Hunk[]>()
  let path: string | null = null
  let h: Hunk | null = null
  let oldPath: string | null = null
  for (const line of out.split('\n')) {
    if (line.startsWith('diff --git ')) { h = null; path = null; oldPath = null; continue }
    if (line.startsWith('+++ ')) {
      const p = line.slice(4).trim()
      path = p === '/dev/null' ? oldPath : p.replace(/^b\//, '')
      if (path && !files.has(path)) files.set(path, [])
      continue
    }
    if (line.startsWith('--- ')) { oldPath = line.slice(4).trim().replace(/^a\//, ''); continue }
    const m = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(line)
    if (m && path) {
      h = { oldStart: Number(m[1]), oldLines: m[2] === undefined ? 1 : Number(m[2]), newStart: Number(m[3]), newLines: m[4] === undefined ? 1 : Number(m[4]), lines: [] }
      files.get(path)!.push(h)
      continue
    }
    if (h && (line.startsWith('+') || line.startsWith('-') || line.startsWith(' '))) h.lines.push(line)
  }
  for (const [p, hs] of files) if (hs.length === 0) files.delete(p)
  return files
}

export type Commit = { sha: string; subject: string; files: string[] }

/** Parses `git log --name-only --format=%x1e%h%x1f%s` (newest first). */
export function parseLog(out: string): Commit[] {
  return out.split('\x1e').map(c => c.trim()).filter(Boolean).map(c => {
    const [head, ...rest] = c.split('\n')
    const [sha = '', subject = ''] = (head ?? '').split('\x1f')
    return { sha, subject, files: rest.map(f => f.trim()).filter(Boolean) }
  })
}

const KIND_OF = (s: string): Group['kind'] =>
  /^(fix|bug|hotfix)\b/i.test(s) ? 'fix'
  : /^(test|tests)\b/i.test(s) ? 'test'
  : /^(refactor|cleanup|chore)\b/i.test(s) ? 'refactor'
  : /^(docs?)\b/i.test(s) ? 'docs'
  : /^(ci|build|config|deps)\b/i.test(s) ? 'config'
  : /^(remove|delete|drop)\b/i.test(s) ? 'removal'
  : 'feature'

/**
 * The branch model: one group per commit (subject as title, conventional prefix as kind),
 * uncommitted work as its own group, and the session's group used instead for files this
 * session edited, so its concepts carry over.
 */
export function branchModel(
  root: string, diff: Map<string, Hunk[]>, log: readonly Commit[], uncommitted: ReadonlySet<string>,
  session: Model, read: (abs: string) => string[],
): Model {
  const owner = new Map<string, Commit | 'wip'>()
  for (const p of diff.keys()) if (uncommitted.has(p)) owner.set(p, 'wip')
  for (const c of log) for (const f of c.files) if (diff.has(f) && !owner.has(f)) owner.set(f, c)
  const sessionGroup = new Map<string, string>()
  for (const e of session.edits) if (e.group) sessionGroup.set(e.path, e.group)

  const groups: Group[] = []
  const add = (g: Group) => { if (!groups.some(x => x.id === g.id)) groups.push(g) }
  const edits: Edit[] = []
  let i = 0
  for (const [p, hunks] of diff) {
    const abs = `${root}/${p}`
    const sg = sessionGroup.get(abs)
    const own = owner.get(p)
    let gid: string
    if (sg) {
      const g = session.groups.find(x => x.id === sg)
      if (g) add({ ...g, turn: 0 })
      gid = sg
    } else if (own && own !== 'wip') {
      gid = `c-${own.sha}`
      add({ id: gid, kind: KIND_OF(own.subject), title: own.subject.replace(/^\w+(\([^)]*\))?!?:\s*/, '').slice(0, 70) || own.subject, summary: `commit ${own.sha}`, turn: 0 })
    } else {
      gid = 'wip'
      add({ id: gid, kind: 'feature', title: 'Uncommitted work', summary: 'Changes in the working tree that are not in a commit yet.', turn: 0 })
    }
    const lines = read(abs)
    edits.push({ id: `b${i++}`, turn: 0, path: abs, hunks, ...(hunks.some(h => h.newStart === 0 && h.newLines === 0) ? { deleted: true } : {}), symbols: hunks.map(h => symbolAt(lines, h.newStart)), group: gid })
  }
  // newest commit first, matching the session view (rows() reverses)
  const order = (g: Group) => g.id === 'wip' ? -1 : g.id.startsWith('c-') ? log.findIndex(c => `c-${c.sha}` === g.id) : -2
  groups.sort((a, b) => order(b) - order(a))
  return { ...EMPTY, edits, groups, threads: session.threads, reviewed: session.reviewed, nav: { ...session.nav, scope: 'branch' } }
}

export { slug }

files.hooks/shell.ts:
/* Shell edits: Bash calls that change files (sed -i, heredocs, scripts) give no structured patch,
   so the files a command names are read before and after it runs and the difference is diffed here. */
import type { Hunk } from '../types'

export const MAX_FILES = 40
export const MAX_BYTES = 512 * 1024

const SKIP_DIR = /(^|\/)(\.git|node_modules|\.venv|venv|__pycache__|dist|build|\.next|target)(\/|$)/
const BINARY_EXT = /\.(png|jpe?g|gif|webp|ico|pdf|zip|gz|tgz|tar|jar|class|so|dylib|o|a|bin|pcap|pcapng|mp4|mov|woff2?|ttf|lock)$/i

/**
 * The files a shell command may touch, as absolute paths: path-like words in it, with simple
 * `NAME=value` assignments and `$NAME`/`${NAME}`/`~` expanded, resolved against the session's
 * directory and any directory the command `cd`s into.
 */
export function candidates(command: string, cwd: string, home: string): string[] {
  const vars = new Map<string, string>([['HOME', home]])
  for (const m of command.matchAll(/(?:^|[\s;&|(])([A-Za-z_][A-Za-z0-9_]*)=("([^"]*)"|'([^']*)'|([^\s;&|)]+))/g)) {
    vars.set(m[1]!, m[3] ?? m[4] ?? m[5] ?? '')
  }
  const expand = (s: string) => {
    let out = s
    for (let i = 0; i < 3; i++) {
      out = out.replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g, (all, a, b) => vars.get(a ?? b) ?? all)
    }
    return out.replace(/^~(?=\/|$)/, home)
  }
  const bases = [cwd]
  for (const m of command.matchAll(/(?:^|[;&|(]\s*)cd\s+("([^"]+)"|'([^']+)'|([^\s;&|)]+))/g)) {
    const d = expand(m[2] ?? m[3] ?? m[4] ?? '')
    if (d && !d.includes('$')) bases.push(d.startsWith('/') ? d : `${cwd}/${d}`)
  }
  const out = new Set<string>()
  // words that look like file paths: contain a slash or end in an extension
  for (const m of command.matchAll(/(?:\$\{?[A-Za-z_][A-Za-z0-9_]*\}?|~|\.{1,2}|\/)?[A-Za-z0-9_@%+=:,.\/{}$~-]*[A-Za-z0-9_-]\.[A-Za-z0-9]{1,8}\b|(?:\$\{?[A-Za-z_][A-Za-z0-9_]*\}?|~)\/[A-Za-z0-9_@%+=:,.\/{}$-]+/g)) {
    const raw = expand(m[0].replace(/[,:]+$/, ''))
    if (raw.includes('$') || raw.includes('*') || /^[a-z]+:\/\//i.test(raw) || raw.length > 400) continue
    if (BINARY_EXT.test(raw)) continue
    const tries = raw.startsWith('/') ? [raw] : bases.map(b => `${b}/${raw}`)
    for (const t of tries) {
      const p = normalize(t)
      if (SKIP_DIR.test(p) || p === '/' ) continue
      out.add(p)
    }
    if (out.size >= MAX_FILES * 2) break
  }
  return [...out]
}

export function normalize(p: string): string {
  const parts: string[] = []
  for (const seg of p.split('/')) {
    if (seg === '' || seg === '.') continue
    if (seg === '..') parts.pop()
    else parts.push(seg)
  }
  return '/' + parts.join('/')
}

/**
 * Unified-diff hunks (3 lines of context) between two texts. Common prefix and suffix are trimmed,
 * then the middle is diffed line by line (LCS); a middle too large to diff cheaply becomes one
 * replace hunk, which is still correct, just coarser.
 */
export function diffHunks(before: string, after: string, context = 3): Hunk[] {
  if (before === after) return []
  const a = before === '' ? [] : before.split('\n'), b = after === '' ? [] : after.split('\n')
  let pre = 0
  while (pre < a.length && pre < b.length && a[pre] === b[pre]) pre++
  let suf = 0
  while (suf < a.length - pre && suf < b.length - pre && a[a.length - 1 - suf] === b[b.length - 1 - suf]) suf++
  const am = a.slice(pre, a.length - suf), bm = b.slice(pre, b.length - suf)

  // ops over the middle: ' ' keep, '-' delete, '+' insert
  type Op = { t: ' ' | '-' | '+'; s: string }
  let ops: Op[]
  if (am.length * bm.length > 4_000_000) {
    ops = [...am.map(s => ({ t: '-' as const, s })), ...bm.map(s => ({ t: '+' as const, s }))]
  } else {
    const n = am.length, m = bm.length
    const L: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1))
    for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
      L[i]![j] = am[i] === bm[j] ? L[i + 1]![j + 1]! + 1 : Math.max(L[i + 1]![j]!, L[i]![j + 1]!)
    ops = []
    let i = 0, j = 0
    while (i < n && j < m) {
      if (am[i] === bm[j]) { ops.push({ t: ' ', s: am[i]! }); i++; j++ }
      else if (L[i + 1]![j]! >= L[i]![j + 1]!) ops.push({ t: '-', s: am[i++]! })
      else ops.push({ t: '+', s: bm[j++]! })
    }
    while (i < n) ops.push({ t: '-', s: am[i++]! })
    while (j < m) ops.push({ t: '+', s: bm[j++]! })
  }
  // the whole file as ops, then cut into hunks around the changes
  const all: Op[] = [...a.slice(0, pre).map(s => ({ t: ' ' as const, s })), ...ops, ...a.slice(a.length - suf).map(s => ({ t: ' ' as const, s }))]
  const changed = all.map((o, k) => (o.t !== ' ' ? k : -1)).filter(k => k >= 0)
  const hunks: Hunk[] = []
  let k = 0
  while (k < changed.length) {
    let start = Math.max(0, changed[k]! - context)
    let end = Math.min(all.length - 1, changed[k]! + context)
    while (k + 1 < changed.length && changed[k + 1]! - context <= end + 1) { k++; end = Math.min(all.length - 1, changed[k]! + context) }
    k++
    // line numbers at `start`
    let oldStart = 1, newStart = 1
    for (let x = 0; x < start; x++) { if (all[x]!.t !== '+') oldStart++; if (all[x]!.t !== '-') newStart++ }
    const slice = all.slice(start, end + 1)
    const oldLines = slice.filter(o => o.t !== '+').length
    const newLines = slice.filter(o => o.t !== '-').length
    hunks.push({ oldStart: oldLines === 0 ? oldStart - 1 : oldStart, oldLines, newStart: newLines === 0 ? newStart - 1 : newStart, newLines, lines: slice.map(o => o.t + o.s) })
  }
  return hunks.slice(0, 40)
}

files.hooks/label.ts:
/* The cheap-model fallback for concept names: when a turn edits files and Claude adds no
   <change-group> tag, one small call files the edits under the session's existing concepts,
   or names a new one. Existing concepts come first, so a session builds a few growing concepts
   rather than one per turn. */
import type { Edit, Group, GroupKind } from '../types'
import { KINDS, addedRemoved, slug } from './model.js'

export type Label = { path: string; id: string; isNew: boolean; title?: string; kind?: GroupKind; summary?: string }

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n) + '…' : s)

/** A compact, bounded description of one turn's edits: path, symbols and a few changed lines. */
export function describeEdits(edits: readonly Edit[], rel: (p: string) => string): string {
  const byPath = new Map<string, Edit[]>()
  for (const e of edits) byPath.set(e.path, [...(byPath.get(e.path) ?? []), e])
  const out: string[] = []
  for (const [p, es] of [...byPath].slice(0, 15)) {
    const hunks = es.flatMap(e => e.hunks)
    const { add, del } = addedRemoved(hunks)
    const syms = [...new Set(es.flatMap(e => e.symbols).filter(Boolean))].slice(0, 4)
    const sample = hunks.flatMap(h => h.lines.filter(l => l.startsWith('+') || l.startsWith('-'))).slice(0, 8).map(l => '    ' + clip(l, 110))
    out.push(`- ${rel(p)} (+${add} -${del})${syms.length ? ` in ${syms.join(', ')}` : ''}${es.some(e => e.created) ? ' [new file]' : ''}`, ...sample)
  }
  return out.join('\n').slice(0, 6000)
}

export function labelPrompt(ask: string, edits: string, groups: readonly Group[]): string {
  const existing = groups.length === 0
    ? '(none yet)'
    : groups.slice(-15).map(g => `- id=${g.id} [${g.kind}] ${g.title}${g.summary ? ` — ${clip(g.summary, 140)}` : ''}`).join('\n')
  return `You label a coding session's edits into a few CONCEPTS (features, fixes, behaviour changes) for a review pane.

Existing concepts in this session:
${existing}

What the user asked for this turn:
${clip(ask || '(not available)', 1200)}

This turn's edits:
${edits}

For EACH edited file, answer one line:
  <path> => <existing-id>
or, only if the work is genuinely new and fits no existing concept:
  <path> => NEW <short-id> | <kind> | <title, plain words, <= 8 words> | <one sentence: what it does now and why>
kind is one of: ${KINDS.join(', ')}.
Prefer an existing concept whenever the edit continues or supports it (tests, docs and config for a feature belong with that feature). Files that are part of the same new work share one NEW id; repeat the same title for them. Output only those lines.`
}

/** Reads the call's answer; unknown ids and malformed lines are dropped, never guessed. */
export function parseLabels(reply: string, paths: readonly string[], known: ReadonlySet<string>, rel: (p: string) => string): Label[] {
  const byRel = new Map(paths.map(p => [rel(p), p]))
  const out: Label[] = []
  for (const raw of reply.split('\n')) {
    const line = raw.trim().replace(/^[-*]\s+/, '').replace(/`/g, '')
    const m = /^(.+?)\s*=>\s*(.+)$/.exec(line)
    if (!m) continue
    const p = byRel.get(m[1]!.trim()) ?? paths.find(x => x.endsWith('/' + m[1]!.trim()) || x === m[1]!.trim())
    if (!p || out.some(o => o.path === p)) continue
    const rhs = m[2]!.trim()
    const n = /^NEW\s+([^|]+)\|\s*([^|]+)\|\s*([^|]+)\|?\s*(.*)$/i.exec(rhs)
    if (n) {
      const kind = n[2]!.trim().toLowerCase()
      const title = n[3]!.trim().slice(0, 70)
      if (!title) continue
      out.push({ path: p, id: slug(n[1]!.trim()), isNew: true, title, kind: (KINDS as readonly string[]).includes(kind) ? (kind as GroupKind) : 'feature', summary: n[4]!.trim().slice(0, 300) })
      continue
    }
    const id = rhs.split(/\s/)[0]!.replace(/^id=/, '')
    if (known.has(id)) out.push({ path: p, id, isNew: false })
  }
  return out
}

